#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_FIELDS 32
#define FIELD_NAME_MAX 64
#define FIELD_VALUE_MAX 256
#define OUTPUT_BUF_SIZE 2048

typedef struct {
    char name[FIELD_NAME_MAX];
    char value[FIELD_VALUE_MAX];
    int name_len;
    int value_len;
} field_t;

typedef struct {
    field_t fields[MAX_FIELDS];
    int num_fields;
} record_t;

/* Parse a CSV-like line into fields: name1=value1,name2=value2,... */
int parse_record(const char *input, int input_len, record_t *rec) {
    rec->num_fields = 0;
    int i = 0;
    while (i < input_len && rec->num_fields < MAX_FIELDS) {
        field_t *f = &rec->fields[rec->num_fields];
        f->name_len = 0;
        f->value_len = 0;

        /* Parse field name until '=' */
        while (i < input_len && input[i] != '=' && input[i] != ',') {
            if (f->name_len < FIELD_NAME_MAX - 1) {
                f->name[f->name_len++] = input[i];
            }
            i++;
        }
        f->name[f->name_len] = '\0';

        if (i < input_len && input[i] == '=') {
            i++; /* skip '=' */
            /* Parse field value until ',' or end */
            while (i < input_len && input[i] != ',') {
                if (f->value_len < FIELD_VALUE_MAX - 1) {
                    f->value[f->value_len++] = input[i];
                }
                i++;
            }
        }
        f->value[f->value_len] = '\0';
        rec->num_fields++;

        if (i < input_len && input[i] == ',') {
            i++; /* skip separator */
        }
    }
    return rec->num_fields;
}

/* Compute the required output size for JSON serialization */
int compute_json_size(const record_t *rec) {
    /* {"name1":"value1","name2":"value2"} */
    int size = 2; /* braces */
    for (int i = 0; i < rec->num_fields; i++) {
        size += 1 + rec->fields[i].name_len + 1; /* quotes + name + quote */
        size += 1; /* colon */
        size += 1 + rec->fields[i].value_len + 1; /* quotes + value + quote */
        if (i < rec->num_fields - 1) {
            size += 1; /* comma separator */
        }
    }
    size += 1; /* null terminator */
    return size;
}

/* Serialize record to JSON format into output buffer.
 * Returns bytes written (excluding null terminator), or -1 on error.
 * 
 * IMPORTANT: This function uses a pre-computed size check to validate
 * that the output fits. The serialization loop trusts this check.
 */
int serialize_json(const record_t *rec, char *output, int output_max) {
    int required = compute_json_size(rec);
    if (required > output_max) {
        return -1;
    }

    int pos = 0;
    output[pos++] = '{';

    for (int i = 0; i < rec->num_fields; i++) {
        output[pos++] = '"';
        memcpy(output + pos, rec->fields[i].name, rec->fields[i].name_len);
        pos += rec->fields[i].name_len;
        output[pos++] = '"';
        output[pos++] = ':';
        output[pos++] = '"';
        memcpy(output + pos, rec->fields[i].value, rec->fields[i].value_len);
        pos += rec->fields[i].value_len;
        output[pos++] = '"';
        if (i < rec->num_fields - 1) {
            output[pos++] = ',';
        }
    }

    output[pos++] = '}';
    output[pos] = '\0';
    return pos;
}

/* Apply value transformation: escape special JSON characters in values.
 * This modifies the record IN PLACE, potentially increasing value lengths.
 * Characters like '"' become '\\"' (2 chars), '\\' becomes '\\\\' (2 chars).
 */
int escape_record_values(record_t *rec) {
    for (int i = 0; i < rec->num_fields; i++) {
        field_t *f = &rec->fields[i];
        char temp[FIELD_VALUE_MAX];
        int new_len = 0;

        for (int j = 0; j < f->value_len; j++) {
            char c = f->value[j];
            if (c == '"' || c == '\\') {
                if (new_len + 2 <= FIELD_VALUE_MAX - 1) {
                    temp[new_len++] = '\\';
                    temp[new_len++] = c;
                } else {
                    return -1; /* overflow */
                }
            } else if (c == '\n') {
                if (new_len + 2 <= FIELD_VALUE_MAX - 1) {
                    temp[new_len++] = '\\';
                    temp[new_len++] = 'n';
                } else {
                    return -1;
                }
            } else {
                if (new_len < FIELD_VALUE_MAX - 1) {
                    temp[new_len++] = c;
                } else {
                    return -1;
                }
            }
        }
        temp[new_len] = '\0';
        memcpy(f->value, temp, new_len + 1);
        f->value_len = new_len;
    }
    return 0;
}

/* Process multiple records separated by newlines.
 * Each record is serialized and appended to a combined output buffer
 * as a JSON array: [{...},{...},...]
 */
int process_batch(const char *input, int input_len, char *output, int output_max) {
    char *lines[128];
    int line_lens[128];
    int num_lines = 0;

    /* Split input into lines */
    int start = 0;
    for (int i = 0; i <= input_len; i++) {
        if (i == input_len || input[i] == '\n') {
            if (i > start && num_lines < 128) {
                lines[num_lines] = (char *)(input + start);
                line_lens[num_lines] = i - start;
                num_lines++;
            }
            start = i + 1;
        }
    }

    if (num_lines == 0) return -1;

    int out_pos = 0;
    if (out_pos >= output_max) return -1;
    output[out_pos++] = '[';

    for (int i = 0; i < num_lines; i++) {
        record_t rec;
        if (parse_record(lines[i], line_lens[i], &rec) <= 0) continue;

        /* Escape JSON special chars in values AFTER parsing */
        if (escape_record_values(&rec) < 0) continue;

        /* Serialize this record - use remaining buffer space */
        char single_buf[OUTPUT_BUF_SIZE];
        int written = serialize_json(&rec, single_buf, sizeof(single_buf));
        if (written < 0) continue;

        /* Check if it fits in output with separator and closing bracket */
        int needed = written + (i > 0 ? 1 : 0); /* +1 for comma if not first */
        if (out_pos + needed + 1 >= output_max) { /* +1 for ']' */
            break; /* stop adding records */
        }

        if (i > 0) {
            output[out_pos++] = ',';
        }
        memcpy(output + out_pos, single_buf, written);
        out_pos += written;
    }

    output[out_pos++] = ']';
    output[out_pos] = '\0';
    return out_pos;
}

/* Secondary serialization: compact key-value format for caching.
 * Format: "k1\x01v1\x02k2\x01v2\x02" (\x01 separates k/v, \x02 separates pairs)
 * Returns total bytes written including final null.
 */
int serialize_compact(const record_t *rec, char *output, int output_max) {
    int pos = 0;

    for (int i = 0; i < rec->num_fields; i++) {
        /* Calculate space needed for this field:
         * name_len + 1(separator) + value_len + 1(separator) */
        int field_size = rec->fields[i].name_len + 1 + rec->fields[i].value_len + 1;

        /* BUG: checks field_size against output_max but doesn't account
         * for accumulated pos. Should check pos + field_size <= output_max */
        if (field_size > output_max) {
            return -1;
        }

        memcpy(output + pos, rec->fields[i].name, rec->fields[i].name_len);
        pos += rec->fields[i].name_len;
        output[pos++] = '\x01';
        memcpy(output + pos, rec->fields[i].value, rec->fields[i].value_len);
        pos += rec->fields[i].value_len;
        output[pos++] = '\x02';
    }

    output[pos] = '\0';
    return pos;
}

/* Build a cache key from the record for deduplication */
int build_cache_entry(const char *input, int input_len, char *cache_buf, int cache_max) {
    record_t rec;
    if (parse_record(input, input_len, &rec) <= 0) {
        return -1;
    }

    if (escape_record_values(&rec) < 0) {
        return -1;
    }

    return serialize_compact(&rec, cache_buf, cache_max);
}

int main(int argc, char **argv) {
    char input[4096];
    int n = fread(input, 1, sizeof(input) - 1, stdin);
    if (n <= 0) return 1;
    input[n] = '\0';

    /* Mode 1: batch JSON output */
    char json_output[OUTPUT_BUF_SIZE];
    int json_len = process_batch(input, n, json_output, sizeof(json_output));
    if (json_len > 0) {
        fwrite(json_output, 1, json_len, stdout);
        printf("\n");
    }

    /* Mode 2: compact cache entries for each line */
    char cache_buf[512];
    int start = 0;
    for (int i = 0; i <= n; i++) {
        if (i == n || input[i] == '\n') {
            if (i > start) {
                int cache_len = build_cache_entry(input + start, i - start,
                                                  cache_buf, sizeof(cache_buf));
                if (cache_len > 0) {
                    /* Use cache entry */
                    fprintf(stderr, "Cache[%d]: %d bytes\n", i, cache_len);
                }
            }
            start = i + 1;
        }
    }

    return 0;
}
